/**
 * Public project load. `serve` reads the compiled project back from the map.
 */
import { projectInfo } from "./info.js";
import { formatDiagnostics, hasErrorDiagnostics, loadAgentProject } from "./project.js";
const agentProjects = new WeakMap();
class ProjectImpl {
    constructor(info) {
        this.info = info;
    }
}
export class ProjectLoadError extends Error {
    constructor(diagnostics) {
        const copy = diagnostics.map((diagnostic) => ({ ...diagnostic }));
        super(formatDiagnostics(copy));
        this.name = "ProjectLoadError";
        this.diagnostics = copy;
    }
}
export async function loadProject(dir, options = {}) {
    const loaded = await loadAgentProject(dir);
    const hasError = hasErrorDiagnostics(loaded);
    const hasWarning = loaded.diagnostics.some((diagnostic) => diagnostic.severity === "warning");
    if (hasError || (options.strict === true && hasWarning)) {
        throw new ProjectLoadError(loaded.diagnostics);
    }
    return createProject(loaded);
}
export function createProject(agentProject) {
    const project = new ProjectImpl(deepFreeze(projectInfo(agentProject)));
    agentProjects.set(project, agentProject);
    return project;
}
function deepFreeze(value) {
    const copy = structuredClone(value);
    freezeValue(copy);
    return copy;
}
function freezeValue(value) {
    if (value === null || typeof value !== "object" || Object.isFrozen(value)) {
        return;
    }
    for (const nested of Object.values(value)) {
        freezeValue(nested);
    }
    Object.freeze(value);
}
export function unwrapProject(project) {
    const agentProject = project instanceof ProjectImpl ? agentProjects.get(project) : undefined;
    if (agentProject === undefined) {
        throw new Error("serve() accepts a Project from loadProject");
    }
    return agentProject;
}
